alter table jungle.questions add column if not exists max_choices integer not null default 1 check(max_choices between 1 and 3);

create or replace function jungle.score_choice(kind text, correct_answer text, player_choice text, unit_points integer, max_choices integer) returns integer language plpgsql immutable as $$ declare hits integer; begin if kind is distinct from 'settled' or correct_answer is null or player_choice is null then return 0; end if; if max_choices=1 then return case when correct_answer=player_choice then unit_points else 0 end; end if; select count(*) into hits from (select jsonb_array_elements_text(correct_answer::jsonb) intersect select jsonb_array_elements_text(player_choice::jsonb)) x; return hits*unit_points; exception when invalid_text_representation or invalid_parameter_value then return 0; end $$;

create or replace function jungle.perfect_choice(correct_answer text, player_choice text, max_choices integer) returns boolean language plpgsql immutable as $$ begin if correct_answer is null or player_choice is null then return false; end if; if max_choices=1 then return correct_answer=player_choice; end if; return correct_answer::jsonb @> player_choice::jsonb and player_choice::jsonb @> correct_answer::jsonb; exception when invalid_text_representation or invalid_parameter_value then return false; end $$;
